import React from "react";
import Nav from "../Nav/Nav";
import "./Home.css"; 


function Home() {
  return (
    <div className="home-container">
      <Nav />
     
      <div className="welcome-rectangle">
        <h1>Welcome to our order Management system!</h1>
      </div>
    </div>
  );
}

export default Home;
